(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist');
  const content = readFileSync(inputPath, { encoding: 'utf8' });
  try {
    globalThis.parsedData = JSON.parse(content);
  } catch (e) {
    throw new Error('Invalid JSON input');
  }
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { writeFileSync } = await import('node:fs');
  const { encode } = await import('@msgpack/msgpack');
  if (globalThis.parsedData === undefined) throw new Error('No parsed data available');
  const encoded = encode(globalThis.parsedData);
  const buffer = Buffer.from(encoded.buffer, encoded.byteOffset, encoded.byteLength);
  writeFileSync(globalThis.outputPath, buffer);
})();
